import { type ReactNode } from 'react';

type ChipType = 'outlined' | 'filled';
type ChipSize = 'xs' | 's' | 'm' | 'l' | 'xl';

export type ChipProps = {
  type?: ChipType;
  size?: ChipSize;
  disabled?: boolean;
  error?: boolean;
  focused?: boolean;
  animated?: boolean;
  iconLeft?: ReactNode;
  onClose?: () => void;
  children: string;
  className?: string;
};

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

const CloseIcon = () => (
  <svg width="100%" height="100%" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
    <path d="M4.5 4.5l7 7M11.5 4.5l-7 7" />
  </svg>
);

export function Chip({
  type = 'outlined',
  size = 's',
  disabled = false,
  error = false,
  focused = false,
  animated = false,
  iconLeft,
  onClose,
  children,
  className,
}: ChipProps) {
  const classes = cn(
    'chip',
    `chip--${type}`,
    `chip--${size}`,
    disabled && 'chip--disabled',
    error && 'chip--error',
    focused && 'chip--focused',
    className,
  );

  return (
    <span className={classes} {...(animated ? { 'data-chip-animate': '' } : {})}>
      {iconLeft && <span className="chip__icon">{iconLeft}</span>}
      <span className="chip__label">{children}</span>
      {onClose && (
        <button
          type="button"
          className="chip__close"
          onClick={onClose}
          disabled={disabled}
          aria-label={`Remove ${children}`}
          tabIndex={-1}
        >
          <CloseIcon />
        </button>
      )}
    </span>
  );
}

/* -------------------------------------------------------------------------
   Chip

   Interactive tag with optional leading icon and close button.
   Same sizing discipline as Button: height + padding from tokens,
   gap/radius/icon em-relative.

   Types:   outlined, filled
   Sizes:   xs, s, m, l, xl (same naming as Button)
   States:  enabled, hover, pressed, disabled, error
   ------------------------------------------------------------------------- */

.chip {
  display: inline-flex;
  align-items: center;
  gap: 0.375em;
  border-radius: 0.5em;
  border: var(--stroke-thin) solid transparent;
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-medium);
  line-height: 1;
  color: var(--foreground);
  cursor: default;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  white-space: nowrap;
  transition:
    background-color var(--duration-150) var(--easing-out),
    border-color var(--duration-150) var(--easing-out),
    scale var(--duration-150) var(--easing-in-out);
}

.chip[data-chip-animate]:active:not(.chip--disabled) {
  scale: 0.955 0.925;
}

@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .chip[data-chip-animate]:hover:not(.chip--disabled) {
    scale: 1.06 1.095;
    transition:
      background-color 0.15s cubic-bezier(0.19, 1, 0.22, 1),
      border-color 0.15s cubic-bezier(0.19, 1, 0.22, 1),
      scale var(--duration-500) 0.05s cubic-bezier(0.32, 0.72, 0, 1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .chip {
    transition-duration: 0ms;
  }
  .chip:active:not(.chip--disabled) {
    scale: 1;
  }
}

/* ---- Sizes (height + h-padding explicit, font-size uniform) ---- */

.chip--xs {
  height: 1.25rem;
  padding: 0 var(--spacing-1);
}

.chip--s {
  height: 1.5rem;
  padding: 0 var(--spacing-2);
}

.chip--m {
  height: 2rem;
  padding: 0 var(--spacing-2);
}

.chip--l {
  height: 2.5rem;
  padding: 0 var(--spacing-3);
}

.chip--xl {
  height: 3rem;
  padding: 0 var(--spacing-4);
}

/* ---- Types ---- */

.chip--outlined {
  background-color: var(--background);
  border-color: var(--border);
}

.chip--outlined:hover:not(.chip--disabled) {
  background-color: var(--accent);
}

.chip--filled {
  background-color: var(--muted);
}

.chip--filled:hover:not(.chip--disabled) {
  background-color: var(--accent);
}

/* ---- Disabled ---- */

.chip--disabled {
  color: var(--muted-foreground);
  cursor: not-allowed;
  pointer-events: none;
}

.chip--disabled.chip--outlined {
  border-color: var(--muted);
  background-color: var(--muted);
}

.chip--disabled.chip--filled {
  background-color: var(--muted);
}

/* ---- Error ---- */

.chip--error.chip--outlined {
  border-color: var(--destructive);
  color: var(--destructive);
}

.chip--error.chip--outlined:hover:not(.chip--disabled) {
  background-color: color-mix(in srgb, var(--destructive) 6%, var(--background));
}

.chip--error.chip--filled {
  background-color: color-mix(in srgb, var(--destructive) 8%, var(--background));
  color: var(--destructive);
}

.chip--error.chip--filled:hover:not(.chip--disabled) {
  background-color: color-mix(in srgb, var(--destructive) 12%, var(--background));
}

/* ---- Focus ---- */

.chip:focus-visible,
.chip--focused {
  box-shadow: 0 0 0 var(--stroke-medium) var(--focus-ring-color);
  outline: none;
}

/* ---- Parts ---- */

.chip__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1em;
  height: 1em;
}

.chip__icon svg {
  width: 100%;
  height: 100%;
}

.chip__label {
  display: inline-flex;
  align-items: center;
}

.chip__close {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1.125em;
  height: 1.125em;
  padding: 0.125em;
  border: none;
  background-color: color-mix(in srgb, var(--foreground) 6%, transparent);
  color: inherit;
  cursor: pointer;
  border-radius: var(--radius-full);
  transition:
    background-color var(--duration-150) var(--easing-out),
    scale var(--duration-500) cubic-bezier(0.32, 0.72, 0, 1);
}

.chip__close svg {
  width: 100%;
  height: 100%;
}

.chip__close:active {
  scale: 0.9;
}

.chip--error .chip__close {
  background-color: color-mix(in srgb, var(--destructive) 10%, transparent);
}

.chip--disabled .chip__close {
  cursor: not-allowed;
  pointer-events: none;
  background-color: color-mix(in srgb, var(--foreground) 4%, transparent);
}

@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .chip__close:hover {
    background-color: color-mix(in srgb, var(--foreground) 12%, transparent);
    scale: 1.06 1.095;
  }

  .chip--error .chip__close:hover {
    background-color: color-mix(in srgb, var(--destructive) 18%, transparent);
  }
}
